import{_ as r,a0 as p,w as o,s as u,I as t,x as a,a1 as l,A as e,ao as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const h=JSON.parse('{"title":"在 Linux 上安装 VMware 工具 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 上安装 VMware 工具 | LCTT (201910) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 上安装 VMware 工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 上安装 VMware 工具 | LCTT (201910) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201910/20190301 Guide to Install VMware Tools on Linux","title":"在 Linux 上安装 VMware 工具","tag":"201910","desc":""},"relativePath":"201910/20190301 Guide to Install VMware Tools on Linux.md","filePath":"[post].md"}'),w={name:"201910/20190301 Guide to Install VMware Tools on Linux.md"};function d(m,s,V,f,M,g){const n=p("Link");return o(),u("div",null,[s[24]||(s[24]=t("h1",{id:"在-linux-上安装-vmware-工具",tabindex:"-1"},[a("在 Linux 上安装 VMware 工具 "),t("a",{class:"header-anchor",href:"#在-linux-上安装-vmware-工具","aria-label":"Permalink to “在 Linux 上安装 VMware 工具”"},"​")],-1)),s[25]||(s[25]=t("blockquote",null,[t("p",null,"VMware 工具通过允许你共享剪贴板和文件夹以及其他东西来提升你的虚拟机体验。了解如何在 Ubuntu 和其它 Linux 发行版上安装 VMware 工具。")],-1)),s[26]||(s[26]=t("p",null,[t("img",{src:"https://i1.wp.com/itsfoss.com/wp-content/uploads/2019/03/install-vmware-tools-linux.png?resize=800%2C450&ssl=1",alt:"如何在 Linux 上安装 VMware 工具"})],-1)),t("p",null,[s[1]||(s[1]=a("在先前的教程中，你学习了",-1)),l(n,{href:"https://itsfoss.com/install-vmware-player-ubuntu-1310/"},{default:e(()=>[...s[0]||(s[0]=[a("在 Ubuntu 上安装 VMware 工作站",-1)])]),_:1}),s[2]||(s[2]=a("。你还可以通过安装 VMware 工具进一步提升你的虚拟机功能。",-1))]),t("p",null,[s[4]||(s[4]=a("如果你已经在 VMware 上安装了一个访客机系统，你必须要注意 ",-1)),l(n,{href:"https://kb.vmware.com/s/article/340"},{default:e(()=>[...s[3]||(s[3]=[a("VMware 工具",-1)])]),_:1}),s[5]||(s[5]=a("的要求 —— 尽管并不完全清楚到底有什么要求。",-1))]),s[27]||(s[27]=i('<p>在本文中，我们将要强调 VMware 工具的重要性、所提供的特性，以及在 Ubuntu 和其它 Linux 发行版上安装 VMware 工具的方法。</p><h3 id="vmware-工具-概览及特性" tabindex="-1">VMware 工具：概览及特性 <a class="header-anchor" href="#vmware-工具-概览及特性" aria-label="Permalink to “VMware 工具：概览及特性”">​</a></h3><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2019/02/vmware-tools-downloading.jpg?fit=800%2C531&amp;ssl=1" alt="在 Ubuntu 上安装 VMware 工具"></p><p>出于显而易见的理由，虚拟机（你的访客机系统）并不能做到与宿主机上的表现完全一致。在其性能和操作上会有特定的限制。那就是为什么引入 VMware 工具的原因。</p><p>VMware 工具以一种高效的形式在提升了其性能的同时，也可以帮助管理访客机系统。</p><h4 id="vmware-工具到底负责什么" tabindex="-1">VMware 工具到底负责什么？ <a class="header-anchor" href="#vmware-工具到底负责什么" aria-label="Permalink to “VMware 工具到底负责什么？”">​</a></h4><p>你大致知道它可以做什么，但让我们探讨一下细节：</p><ul><li>同步访客机系统与宿主机系统间的时间以简化操作</li><li>提供从宿主机系统向访客机系统传递消息的能力。比如说，你可以复制文字到剪贴板，并将它轻松粘贴到你的访客机系统</li><li>在访客机系统上启用声音</li><li>提升访客机视频分辨率</li><li>修正错误的网络速度数据</li><li>减少不合适的色深</li></ul><p>在访客机系统上安装了 VMware 工具会给它带来显著改变，但是它到底包含了什么特性才解锁或提升这些功能的呢？让我们来看看……</p><h4 id="vmware-工具-核心特性细节" tabindex="-1">VMware 工具：核心特性细节 <a class="header-anchor" href="#vmware-工具-核心特性细节" aria-label="Permalink to “VMware 工具：核心特性细节”">​</a></h4><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2019/02/vmware-tools-features.gif?resize=800%2C500&amp;ssl=1" alt="用 VMware 工具在宿主机系统与访客机系统间共享剪切板"></p><p>如果你不想知道它包含什么来启用这些功能的话，你可以跳过这部分。但是为了好奇的读者，让我们简短地讨论它一下：</p><p><strong>VMware 设备驱动：</strong> 它具体取决于操作系统。大多数主流操作系统都默认包含了设备驱动，因此你不必另外安装它。这主要涉及到内存控制驱动、鼠标驱动、音频驱动、网卡驱动、VGA 驱动以及其它。</p><p><strong>VMware 用户进程：</strong> 这是这里真正有意思的地方。通过它你获得了在访客机和宿主机间复制粘贴和拖拽的能力。基本上，你可以从宿主机复制粘贴文本到虚拟机，反之亦然。</p><p>你同样也可以拖拽文件。此外，在你未安装 SVGA 驱动时它会启用鼠标指针的释放/锁定。</p><p><strong>VMware 工具生命周期管理：</strong> 嗯，我们会在下面看看如何安装 VMware 工具，但是这个特性帮你在虚拟机中轻松安装/升级 VMware 工具。</p><p><strong>共享文件夹</strong>：除了这些。VMware 工具同样允许你在访客机与宿主机系统间共享文件夹。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2019/02/vmware-tools-shared-folder.jpg?fit=800%2C660&amp;ssl=1" alt="使用 VMware 工具在访客机与宿机系统间共享文件"></p><p>当然，它的效果同样取决于访客机系统。例如在 Windows 上你通过 Unity 模式运行虚拟机上的程序并从宿主机系统上操作它。</p><h3 id="如何在-ubuntu-和其它-linux-发行版上安装-vmware-工具" tabindex="-1">如何在 Ubuntu 和其它 Linux 发行版上安装 VMware 工具 <a class="header-anchor" href="#如何在-ubuntu-和其它-linux-发行版上安装-vmware-工具" aria-label="Permalink to “如何在 Ubuntu 和其它 Linux 发行版上安装 VMware 工具”">​</a></h3><p><strong>注意：</strong> 对于 Linux 操作系统，你应该已经安装好了“Open VM 工具”，大多数情况下免除了额外安装 VMware 工具的需要。</p>',21)),t("p",null,[s[7]||(s[7]=a("大部分时候，当你安装了访客机系统时，如果操作系统支持 ",-1)),l(n,{href:"https://docs.vmware.com/en/VMware-Workstation-Player-for-Linux/15.0/com.vmware.player.linux.using.doc/GUID-3F6B9D0E-6CFC-4627-B80B-9A68A5960F60.html"},{default:e(()=>[...s[6]||(s[6]=[a("Easy Install",-1)])]),_:1}),s[8]||(s[8]=a(" 的话你会收到软件更新或弹窗告诉你要安装 VMware 工具。",-1))]),s[28]||(s[28]=i(`<p>Windows 和 Ubuntu 都支持 Easy Install。因此如果你使用 Windows 作为你的宿主机或尝试在 Ubuntu 上安装 VMware 工具，你应该会看到一个和弹窗消息差不多的选项来轻松安装 VMware 工具。这是它应该看起来的样子：</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2019/02/vmware-tools.jpg?fit=800%2C481&amp;ssl=1" alt="安装 VMware 工具的弹窗"></p><p>这是搞定它最简便的办法。因此当你配置虚拟机时确保你有一个通畅的网络连接。</p><p>如果你没收到任何弹窗或者选项来轻松安装 VMware 工具。你需要手动安装它。以下是如何去做：</p><ol><li><p>运行 VMware Workstation Player。</p></li><li><p>从菜单导航至 “Virtual Machine -&gt; Install VMware tools”。如果你已经安装了它并想修复安装，你会看到 “Re-install VMware tools” 这一选项出现。</p></li><li><p>一旦你点击了，你就会看到一个虚拟 CD/DVD 挂载在访客机系统上。</p></li><li><p>打开该 CD/DVD，并复制粘贴那个 tar.gz 文件到任何你选择的区域并解压，这里我们选择“桌面”作为解压目的地。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2019/02/vmware-tools-extraction.jpg?fit=800%2C564&amp;ssl=1" alt=""></p></li><li><p>在解压后，运行终端并通过输入以下命令导航至里面的文件夹：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span></span></span></code></pre></div></li></ol><p>cd Desktop/VMwareTools-10.3.2-9925305/vmware-tools-distrib</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span></span></span>
<span class="line"><span>    你需要检查文件夹与路径名，这取决于版本与解压目的地，名字可能会改变。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    ![][10]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    用你的存储位置（如“下载”）替换“桌面”，如果你安装的也是 10.3.2 版本，其它的保持一样即可。</span></span>
<span class="line"><span>6. 现在仅需输入以下命令开始安装：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    \`\`\`</span></span>
<span class="line"><span>sudo ./vmware-install.pl -d</span></span></code></pre></div><pre><code>![][11]

你会被询问密码以获得安装权限，输入密码然后应当一切都搞定了。
</code></pre><p>到此为止了，你搞定了。这系列步骤应当适用于几乎大部分基于 Ubuntu 的访客机系统。如果你想要在 Ubuntu 服务器上或其它系统安装 VMware 工具，步骤应该类似。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>在 Ubuntu Linux 上安装 VMware 工具应该挺简单。除了简单办法，我们也详述了手动安装的方法。如果你仍需帮助或者对安装有任何建议，在评论区评论让我们知道。</p><hr>`,12)),t("p",null,[s[10]||(s[10]=a("via: ",-1)),l(n,{href:"https://itsfoss.com/install-vmware-tools-linux"},{default:e(()=>[...s[9]||(s[9]=[a("https://itsfoss.com/install-vmware-tools-linux",-1)])]),_:1})]),t("p",null,[s[15]||(s[15]=a("作者：",-1)),l(n,{href:"https://itsfoss.com/author/ankush/"},{default:e(()=>[...s[11]||(s[11]=[a("Ankush Das",-1)])]),_:1}),s[16]||(s[16]=a(" 选题：",-1)),l(n,{href:"https://github.com/lujun9972"},{default:e(()=>[...s[12]||(s[12]=[a("lujun9972",-1)])]),_:1}),s[17]||(s[17]=a(" 译者：",-1)),l(n,{href:"https://github.com/tomjlw"},{default:e(()=>[...s[13]||(s[13]=[a("tomjlw",-1)])]),_:1}),s[18]||(s[18]=a(" 校对：",-1)),l(n,{href:"https://github.com/wxy"},{default:e(()=>[...s[14]||(s[14]=[a("wxy",-1)])]),_:1})]),t("p",null,[s[21]||(s[21]=a("本文由 ",-1)),l(n,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[19]||(s[19]=[a("LCTT",-1)])]),_:1}),s[22]||(s[22]=a(" 原创编译，",-1)),l(n,{href:"https://linux.cn/"},{default:e(()=>[...s[20]||(s[20]=[a("Linux中国",-1)])]),_:1}),s[23]||(s[23]=a(" 荣誉推出",-1))])])}const k=r(w,[["render",d]]);export{h as __pageData,k as default};
